/* ======================= DATABASE ======================= */
const db = new DatabaseSync(path.join(DATA_DIR, 'birzumda.db'));
db.exec(`
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY, phone TEXT UNIQUE NOT NULL, name TEXT DEFAULT '', grp TEXT DEFAULT '',
  created INTEGER NOT NULL, blocked INTEGER DEFAULT 0, noshows INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS otp (
  phone TEXT PRIMARY KEY, code_hash TEXT, expires INTEGER, attempts INTEGER DEFAULT 0,
  last_sent INTEGER DEFAULT 0, window_start INTEGER DEFAULT 0, sent_count INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (
  token TEXT PRIMARY KEY, kind TEXT NOT NULL, user_id INTEGER, created INTEGER, expires INTEGER);
CREATE TABLE IF NOT EXISTS menu (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT DEFAULT 'Issiq', price INTEGER NOT NULL,
  prep_min INTEGER DEFAULT 5, daily_limit INTEGER DEFAULT 100, available INTEGER DEFAULT 1,
  icon TEXT DEFAULT 'plov', image TEXT DEFAULT '', description TEXT DEFAULT '', sort INTEGER DEFAULT 0, deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS slots (
  id INTEGER PRIMARY KEY, time TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 50, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (
  id INTEGER PRIMARY KEY, day TEXT NOT NULL, slot_id INTEGER, slot_time TEXT NOT NULL, code TEXT NOT NULL,
  user_id INTEGER NOT NULL, user_name TEXT, user_phone TEXT, items TEXT NOT NULL, total INTEGER NOT NULL,
  pay_method TEXT NOT NULL, paid INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', note TEXT DEFAULT '',
  created INTEGER NOT NULL, cooking_at INTEGER, ready_at INTEGER, done_at INTEGER);
CREATE INDEX IF NOT EXISTS orders_day ON orders(day);
CREATE INDEX IF NOT EXISTS orders_user ON orders(user_id);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS push_subs (
  id INTEGER PRIMARY KEY, user_id INTEGER, endpoint TEXT UNIQUE, created INTEGER);
CREATE TABLE IF NOT EXISTS notifications (
  id INTEGER PRIMARY KEY, user_id INTEGER, title TEXT, body TEXT, created INTEGER, read INTEGER DEFAULT 0);
`);

const q = (sql) => db.prepare(sql);
const getSetting = (k, d = '') => { const r = q('SELECT value FROM settings WHERE key=?').get(k); return r ? r.value : d; };
const setSetting = (k, v) => q('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(k, String(v));

function hashSecret(s) { const salt = crypto.randomBytes(16).toString('hex'); return salt + ':' + crypto.scryptSync(String(s), salt, 32).toString('hex'); }
function checkSecret(s, stored) {
  if (!stored || !stored.includes(':')) return false;
  const [salt, h] = stored.split(':'); const a = crypto.scryptSync(String(s), salt, 32); const b = Buffer.from(h, 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

