route('POST', '/api/auth/otp', async ({ req, body }) => {
  rateLimit('otp-ip:' + ip(req), 20, 3600e3);
  const phone = normPhone(body.phone); if (!phone) fail(400, "Telefon raqamni +998 XX XXX XX XX ko'rinishida kiriting");
  const ac = getSetting('access_code');
  if (ac && clampStr(body.access_code, 40).toLowerCase() !== ac.toLowerCase()) fail(403, "Pilot kirish kodi noto'g'ri (oshxonadagi plakatda yozilgan)");
  const now = Date.now(); const row = q('SELECT * FROM otp WHERE phone=?').get(phone);
  if (row && now - row.last_sent < 60e3) fail(429, 'Yangi kodni 1 daqiqadan keyin so\'rang');
  let count = row && now - row.window_start < 3600e3 ? row.sent_count : 0;
  if (count >= 5) fail(429, 'Bu raqamga juda ko\'p kod so\'raldi. 1 soatdan keyin urinib ko\'ring.');
  const code = String(crypto.randomInt(1000, 10000));
  q(`INSERT INTO otp(phone,code_hash,expires,attempts,last_sent,window_start,sent_count) VALUES(?,?,?,0,?,?,?)
     ON CONFLICT(phone) DO UPDATE SET code_hash=excluded.code_hash, expires=excluded.expires, attempts=0, last_sent=excluded.last_sent, window_start=excluded.window_start, sent_count=excluded.sent_count`)
    .run(phone, hashSecret(code), now + 5 * 60e3, now, count === 0 ? now : row.window_start, count + 1);
  const text = `Bir Zumda: kirish kodi ${code}. Hech kimga bermang.`;
  if (smsConfigured()) { try { await sendSms(phone, text); } catch (e) { console.error(e.message); fail(502, 'SMS yuborib bo\'lmadi, keyinroq urinib ko\'ring'); } return { sent: true }; }
  console.log(`[SMS sinov rejimi] ${fmtPhone(phone)} → ${code}`);
  return { sent: true, devCode: process.env.HIDE_DEV_CODE === '1' ? undefined : code };
});
route('POST', '/api/auth/verify', ({ req, res, body }) => {
  rateLimit('verify-ip:' + ip(req), 40, 3600e3);
  const phone = normPhone(body.phone); const row = phone && q('SELECT * FROM otp WHERE phone=?').get(phone);
  if (!row || row.expires < Date.now()) fail(400, 'Kod eskirgan. Yangi kod so\'rang.');
  if (row.attempts >= 5) fail(429, 'Urinishlar tugadi. Yangi kod so\'rang.');
  if (!checkSecret(clampStr(body.code, 6), row.code_hash)) { q('UPDATE otp SET attempts=attempts+1 WHERE phone=?').run(phone); fail(400, "Kod noto'g'ri"); }
  q('DELETE FROM otp WHERE phone=?').run(phone);
  let user = q('SELECT * FROM users WHERE phone=?').get(phone);
  if (!user) { q('INSERT INTO users(phone,created) VALUES(?,?)').run(phone, Date.now()); user = q('SELECT * FROM users WHERE phone=?').get(phone); }
  newSession(req, res, 'student', user.id, 60);
  return { user: { id: user.id, name: user.name, grp: user.grp, phone: fmtPhone(user.phone) }, needsProfile: !user.name };
});
