route('POST', '/api/orders', ({ user, body }) => {
  if (!user.name) fail(400, 'Avval ismingizni kiriting');
  const day = body.day === tomorrowStr() ? tomorrowStr() : dayStr();
  const slot = q('SELECT * FROM slots WHERE id=? AND active=1').get(+body.slotId); if (!slot) fail(400, 'Olish vaqtini tanlang');
  const info = slotsFor(day).find(s => s.id === slot.id);
  if (!info.open) fail(409, info.full ? `${slot.time} sloti to'lgan, boshqasini tanlang` : `${slot.time} sloti uchun buyurtma ${info.closes} da yopilgan`);
  const active = q(`SELECT COUNT(*) c FROM orders WHERE user_id=? AND status IN ('new','cooking','ready')`).get(user.id).c;
  if (active >= +getSetting('max_active')) fail(409, `Bir vaqtda ${getSetting('max_active')} tadan ortiq faol buyurtma bo'lmaydi`);
  const raw = Array.isArray(body.items) ? body.items : []; if (!raw.length || raw.length > 15) fail(400, "Savat bo'sh");
  const sold = itemsSoldToday(day); const items = []; let total = 0;
  for (const it of raw) {
    const m = q('SELECT * FROM menu WHERE id=? AND deleted=0').get(+it.id); const qty = intIn(it.qty, 1, 10, 0);
    if (!m || !qty) fail(400, 'Taom topilmadi');
    if (!m.available) fail(409, `${m.name} hozir sotuvda yo'q`);
    if ((sold[m.id] || 0) + qty > m.daily_limit) fail(409, `${m.name} dan faqat ${Math.max(0, m.daily_limit - (sold[m.id] || 0))} ta qoldi`);
    items.push({ id: m.id, name: m.name, price: m.price, qty }); total += m.price * qty;
  }
  const pay = 'window'; // onlayn to'lov (Payme/Click) merchant integratsiyasidan keyin qo'shiladi
  const used = new Set(q('SELECT code FROM orders WHERE day=?').all(day).map(r => r.code));
  let code; do { code = String(crypto.randomInt(1000, 10000)); } while (used.has(code));
  const r = q(`INSERT INTO orders(day,slot_id,slot_time,code,user_id,user_name,user_phone,items,total,pay_method,paid,status,created) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`)
    .run(day, slot.id, slot.time, code, user.id, user.name, user.phone, JSON.stringify(items), total, pay, 0, 'new', Date.now());
  const o = q('SELECT * FROM orders WHERE id=?').get(r.lastInsertRowid);
  orderChanged(o); sse.all('menu', {});
  notify(user.id, 'Buyurtma qabul qilindi', `Kod ${code}. Olish vaqti ${day === dayStr() ? 'bugun' : 'ertaga'} ${slot.time}.`);
  return orderOut(o);
}, 'student');
