route('POST', '/api/admin/menu/:id/image', ({ params, body }) => {
  const m = q('SELECT * FROM menu WHERE id=? AND deleted=0').get(+params.id); if (!m) fail(404, 'Topilmadi');
  if (body.remove) { q("UPDATE menu SET image='' WHERE id=?").run(m.id); sse.all('menu', {}); return { image: '' }; }
  const mt = String(body.dataUrl || '').match(/^data:image\/(webp|jpeg|png);base64,([A-Za-z0-9+/=]+)$/); if (!mt) fail(400, 'Rasm formati: JPG, PNG yoki WebP');
  const buf = Buffer.from(mt[2], 'base64'); if (buf.length > 1.5e6) fail(413, 'Rasm 1.5 MB dan kichik bo\'lsin');
  const name = `m${m.id}-${Date.now()}.${mt[1] === 'jpeg' ? 'jpg' : mt[1]}`;
  fs.writeFileSync(path.join(UPLOAD_DIR, name), buf);
  if (m.image) fs.rm(path.join(UPLOAD_DIR, path.basename(m.image)), () => {});
  q('UPDATE menu SET image=? WHERE id=?').run('/uploads/' + name, m.id); sse.all('menu', {});
  return { image: '/uploads/' + name };
}, 'admin');
