route('GET', '/api/admin/stats', ({ query }) => {
  const day = /^\d{4}-\d{2}-\d{2}$/.test(query.day || '') ? query.day : dayStr();
  const os = q('SELECT * FROM orders WHERE day=?').all(day);
  const valid = os.filter(o => o.status !== 'cancelled');
  const done = os.filter(o => o.status === 'done' && o.ready_at && o.done_at);
  const top = {}; valid.forEach(o => JSON.parse(o.items).forEach(i => top[i.name] = (top[i.name] || 0) + i.qty));
  const days = []; for (let i = 6; i >= 0; i--) { const d = new Date(); d.setDate(d.getDate() - i); const ds = dayStr(d);
    const r = q("SELECT COUNT(*) c, COALESCE(SUM(CASE WHEN status='done' THEN total ELSE 0 END),0) rev FROM orders WHERE day=? AND status!='cancelled'").get(ds); days.push({ day: ds, orders: r.c, revenue: r.rev }); }
  return {
    day, orders: valid.length, active: os.filter(o => ACTIVE.includes(o.status)).length,
    revenue: os.filter(o => o.status === 'done').reduce((s, o) => s + o.total, 0),
    expected: valid.filter(o => o.status !== 'noshow').reduce((s, o) => s + o.total, 0),
    avgWaitSec: done.length ? Math.round(done.reduce((s, o) => s + (o.done_at - o.ready_at), 0) / done.length / 1000) : null,
    avgCookSec: (() => { const c = os.filter(o => o.cooking_at && o.ready_at); return c.length ? Math.round(c.reduce((s, o) => s + (o.ready_at - o.cooking_at), 0) / c.length / 1000) : null; })(),
    noshow: os.filter(o => o.status === 'noshow').length, cancelled: os.filter(o => o.status === 'cancelled').length,
    byStatus: Object.fromEntries(STATUSES.map(s => [s, os.filter(o => o.status === s).length])),
    slots: q('SELECT * FROM slots ORDER BY time').all().map(s => ({ time: s.time, capacity: s.capacity, used: valid.filter(o => o.slot_id === s.id).length, active: s.active })),
    top: Object.entries(top).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([name, qty]) => ({ name, qty })),
    students: q('SELECT COUNT(*) c FROM users').get().c, newStudents: q('SELECT COUNT(*) c FROM users WHERE created > ?').get(Date.now() - 7 * 864e5).c,
    days,
  };
}, 'admin');
route('GET', '/api/admin/students', () => q(`SELECT u.id,u.phone,u.name,u.grp,u.created,u.blocked,u.noshows,
   (SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id AND o.status='done') orders,
   (SELECT COALESCE(SUM(total),0) FROM orders o WHERE o.user_id=u.id AND o.status='done') spent
   FROM users u ORDER BY u.id DESC LIMIT 1000`).all().map(u => ({ ...u, phone: fmtPhone(u.phone) })), 'admin');
route('POST', '/api/admin/students/:id/block', ({ params, body }) => { q('UPDATE users SET blocked=? WHERE id=?').run(body.blocked ? 1 : 0, +params.id); if (body.blocked) q("DELETE FROM sessions WHERE kind='student' AND user_id=?").run(+params.id); return { ok: true }; }, 'admin');
route('GET', '/api/admin/export.csv', ({ res, query }) => {
  const from = /^\d{4}-\d{2}-\d{2}$/.test(query.from || '') ? query.from : dayStr();
  const to = /^\d{4}-\d{2}-\d{2}$/.test(query.to || '') ? query.to : from;
  const rows = q('SELECT * FROM orders WHERE day>=? AND day<=? ORDER BY day, id').all(from, to);
  const cell = v => { const s = String(v ?? ''); return /[",\n;]/.test(s) || /^[=+\-@]/.test(s) ? '"' + s.replace(/^([=+\-@])/, "'$1").replace(/"/g, '""') + '"' : s; };
  const lines = [['Sana', 'Slot', 'Kod', 'Talaba', 'Telefon', 'Taomlar', "Summa (so'm)", "To'lov", 'Holat', 'Yaratildi'].join(',')];
  for (const o of rows) lines.push([o.day, o.slot_time, o.code, o.user_name, fmtPhone(o.user_phone || '998000000000').slice(1), JSON.parse(o.items).map(i => `${i.name} x${i.qty}`).join('; '), o.total, o.pay_method === 'online' ? 'Onlayn' : 'Oynada', o.status, new Date(o.created).toLocaleString('ru-RU')].map(cell).join(','));
  res.writeHead(200, { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': `attachment; filename="birzumda-${from}_${to}.csv"` });
  res.end('﻿' + lines.join('\n'));
}, 'admin');

server.listen(PORT, () => console.log(`Bir Zumda ishlayapti: http://localhost:${PORT}  (talaba: /, oshxona: /oshxona, admin: /admin)`));

/* ======================= .env loader ======================= */
function loadEnvFile(file) {
  if (!fs.existsSync(file)) return;
  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/); if (!m || line.trim().startsWith('#')) continue;
    if (process.env[m[1]] === undefined) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
}
